 mnx=min(x for x,y in points);mny=min(y for x,y in points);return {(x-mnx,y-mny) for x,y in points}
def variants(shape):
 out=[]
 for k in range(8):
  q=[]
  for x,y in shape:
   if k>=4: y=-y
   for _ in range(k%4): x,y=y,-x
   q.append((x,y))
  out.append(normshape(q))
 return out
