def transforms(points):
 for k in range(8):
  q=[]
  for x,y in points:
   if k>=4:y=-y
   for _ in range(k%4):x,y=y,-x
   q.append((x,y))
  mnx=min(x for x,y in q);mny=min(y for x,y in q)
  yield k,{(x-mnx,y-mny) for x,y in q}
